select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('menu-code','کد منو','text',true,10,'{}'),('menu-title','عنوان منو','text',true,20,'{}'),('menu-key','کلید منو','text',true,30,'{}'),('parent-code','کد منوی والد','text',false,40,'{}'),('menu-type','نوع منو','select',true,50,'{"options":["گروه اصلی","زیرمنو","صفحه","عملیات"]}'),('route','مسیر','text',false,60,'{}'),('icon','آیکون','text',false,70,'{}'),('order-index','ترتیب نمایش','number',true,80,'{}'),('access-level','سطح دسترسی','select',true,90,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی"]}'),('visibility','نمایش','select',true,100,'{"options":["نمایش داده شود","مخفی","فقط موبایل","فقط دسکتاپ"]}'),('status','وضعیت','select',true,110,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('target','نحوه بازشدن','select',false,120,'{"options":["همین صفحه","صفحه جدید","پنجره داخلی"]}'),('permission','مجوز موردنیاز','text',false,130,'{}'),('description','توضیحات','textarea',false,140,'{}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='33-menu-builder' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
