insert into platform_modules(code,title,is_active) values ('33-menu-builder','مدیریت منوی مرکزی سازمان',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده منوها','modules:33-menu-builder:read'),('write','ساخت و ویرایش منو','modules:33-menu-builder:write'),('delete','حذف منو','modules:33-menu-builder:delete'),('publish','انتشار منو','modules:33-menu-builder:publish'),('disable','غیرفعال‌سازی','modules:33-menu-builder:disable'),('duplicate','تکثیر منو','modules:33-menu-builder:duplicate'),('reorder','تنظیم ترتیب','modules:33-menu-builder:reorder')) v(a,t,p) where m.code='33-menu-builder' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;